"""Publish completed25 scores only after every cohort reaches its target."""
import hashlib,json
from pathlib import Path
HERE=Path(__file__).resolve().parent;ROOT=HERE.parents[1]
a=json.loads((HERE/'aggregate.json').read_text());assert a['ready'];models={m['key']:m for m in a['models']}
p=ROOT/'README.md';s=p.read_text();start=s.index('**Canonical speech-v2 results, September 15, 2026.**');end=s.index('### Sample Recordings',start)
assert hashlib.sha256(s[:start].encode()).hexdigest()==(HERE/'readme-prefix.sha256').read_text().strip(),'Text-model prefix changed; review before publishing'
def ms(v):return '—' if v is None else f'{v:.0f}ms'
def failure(m):return f"{m['failed_conversations']}/{m['eligible_attempts']} ({m['failure_rate_percent']:.1f}%)"
lines=['**Completed-conversation speech results, September 16, 2026.** Each row scores the first **25 complete, harness-valid conversations (750 turns)** using the shared speech-v2 prompt and Opus 5 rubric. Accuracy is conditional on conversation completion. Incomplete conversations, including their observed prefixes, are excluded from accuracy and reported separately as failed conversations. Every attempt is preserved; failures are not erased by top-ups.','','Failure rate is incomplete model/service conversations divided by harness-valid attempts. Harness-invalid captures are excluded from that denominator and disclosed separately. No prompts or judge rubric changed for this policy update; text-model scores remain unchanged. See the [completed-conversation report](docs/speech-completed25-2026-09-16/REPORT.md) and [sampling policy](docs/speech-completed25-2026-09-16/PROTOCOL.md).','','| Model | Scored | Failed conversations | Pass Rate | Tool Use | Instruction | KB Ground | Turn Ok | Non-Tool V2V Med | Non-Tool V2V Max | Tool V2V Mean | Silence Pad Mean |','|---|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|']
keys=['grok','openai21','openai15','gemini38medium_old','gemini38low','gemini31','live_standard']
for k in sorted(keys,key=lambda k:models[k]['strict_percent'],reverse=True):
 m=models[k];v=m['scores'];label=m['label']+(' + Terra medium' if k=='live_standard' else '')
 lines.append(f"| {label} | 25 | {failure(m)} | {m['strict_percent']:.1f}% | {v['tool_use_correct']}/750 | {v['instruction_following']}/750 | {v['kb_grounding']}/750 | {v['turn_taking']}/750 | {ms(m['non_tool']['median_ms'])} | {ms(m['non_tool']['max_ms'])} | {ms(m['tool']['mean_ms'])} | {ms(m['silence']['mean_ms'])} |")
lines+=['','### Additional speech experiments','','These rows also contain 25 completed conversations. Gemini medium uses the interaction-aware harness; GPT-Live prompt-optimized uses the separately approved frontend/backend prompt split, Terra medium, and the five-second event/playback gate. They remain separate from the earlier harness and standard-prompt cohorts. No runtime transcript classifier is used.','','| Model / configuration | Scored | Failed conversations | Pass Rate | First-speech V2V mean | Median | Positive latency coverage |','|---|---:|---:|---:|---:|---:|---:|']
for k in ['gemini38medium_new','live_optimized']:
 m=models[k];lines.append(f"| {m['label']} | 25 | {failure(m)} | {m['strict_percent']:.1f}% | {ms(m['first_speech_positive']['mean_ms'])} | {ms(m['first_speech_positive']['median_ms'])} | {m['first_speech_positive']['n']}/750 |")
lines+=['','**Failed-conversation details:** turn numbers below are **one-based, out of 30**. No-response timeouts are not labeled explicit API errors.','']
from collections import Counter
for m in a['models']:
 counts=Counter((f['reason'],f['turn_number'],f['completed_turns']) for f in m['failure_details'])
 for (reason,turn,completed),n in counts.items():
  reason='no-response timeout (90s)' if reason=='TimeoutError' and m['key']=='live_optimized' else reason
  lines.append(f"- **{m['label']}**: {n} failure(s), `{reason}` on turn **{turn}**, after {completed} completed turns.")
lines+=['','**Harness and measurement notes:**','','- Gemini 3.8 low: one original capture recorded a startup greeting instead of the first scripted exchange. It is excluded as a harness defect and replaced; the old dagger no longer applies to the scored set. It is not counted as a provider failure.','- GPT-Live standard: waveform landmark alignment resolved the late input-window offset in one recording without changing its measured latencies. The original broken-gate cohort remains diagnostic and excluded.','- GPT-Live optimized: canonical VAD missed one brief recorded answer. The conversation is complete; its unmeasurable latency remains missing. Full missing/nonpositive coverage is retained in the report.','- First-speech V2V includes acknowledgments and is conditional on measurable speech. It is not latency to the substantive answer. Metrics use actual recorded speech, not packet arrival. Missing audio boundaries do not become zero-latency observations.','- The earlier Gemini cohorts retain their documented silent-closing audio limitations. The newer medium cohort waits for provider IDLE and closing playback.','- Gemini 3.1 historical reliability: the [August investigation](docs/async-gemini-live-comparison-2026-08-04/root-cause-probes/README.md) reported 18/20 no-response-free conversations and a WebSocket 1006 reconnect in another attempt. Those historical observations are separate from current counts.','- Historical diagnostic campaigns are not pooled into current failure rates. Original [attempt-based results](docs/speech-v2-canonical-2026-09-15/rejudge-policy-compliance-1/REPORT.md) and the [old speech table](docs/speech-v2-canonical-2026-09-15/historical-speech-results.md) remain archived. The original gpt-realtime model remains omitted.','','']
s=s[:start]+'\n'.join(lines)+s[end:]
s=s.replace('Its gate audit passed, but one recording has a late audio-alignment offset; validation remains on hold.', 'Its gate audit passed. The [completed-conversation review](docs/speech-completed25-2026-09-16/REPORT.md) resolved the recording offset by waveform alignment without changing its measured latencies.')
a0=s.index('A separate **GPT-Live prompt-optimized** experiment is drafted');a1=s.index('\n\n## Quick Start',a0)
s=s[:a0]+'''The separate **GPT-Live prompt-optimized** experiment follows the [design document](docs/gpt-live-prompt-optimized-design-2026-09-15/DESIGN.md). Its original runtime-classifier cohort is preserved as diagnostics. The [five-second protocol](docs/gpt-live-optimized-quiet5-2026-09-16/PROTOCOL.md) uses backend lifecycle, speech after backend content availability, and playback; it has no runtime text classifier. The [completed-conversation report](docs/speech-completed25-2026-09-16/REPORT.md) includes the validated 25-completion cohort and separately retained no-response failure. Smoke tests are excluded. Its split prompts remain separate from the standard speech prompt.''' + s[a1:]
s=s.replace('Run 25 attempted 30-turn conversations per model with aiwf_medium_context_speech_v2:', 'Collect 25 complete, harness-valid 30-turn conversations per model with aiwf_medium_context_speech_v2:')
s=s.replace('failures; do not replace incomplete conversations. Use a fresh campaign directory.', 'failures. Add new attempts until 25 valid conversations complete; never select by score.\nExclude incomplete conversations from accuracy and report failure rates separately.\nExclude confirmed harness defects separately from model/service failures. Use a fresh campaign directory.')
s=s.replace('- Complete (X/25), with failure types in footnotes','- Scored conversations (25)\n- Failed conversations / eligible attempts, percentage, failure reason and stopping turn')
s=s.replace('Count missing planned turns as failures, and also report accuracy on observed turns.', 'Score the 750 turns from completed conversations. Preserve partial failed transcripts as\ndiagnostics; report each failure with its one-based stopping turn and completed-turn count.')
s=s.replace('See the [frozen canonical protocol](docs/speech-v2-canonical-2026-09-15/PROTOCOL.md)\nfor capture settings, scoring definitions, and reproducibility artifacts.', 'See the [completed-conversation protocol](docs/speech-completed25-2026-09-16/PROTOCOL.md)\nfor sampling, failure accounting, and links to preserved capture artifacts.')
p.write_text(s);(HERE/'published.json').write_text(json.dumps(dict(readme_sha256=hashlib.sha256(s.encode()).hexdigest(),models=len(models)))+'\n');print('Published completed25 results for',len(models),'cohorts')
